questions.starter:
// HTML on the page:
// <button id="enroll-btn" class="btn">Enroll</button>
// <div id="alert-box" class="alert hidden">Only 3 spots left!</div>

// 1. Add 'active' class to button

// 2. Toggle 'hidden' on alert box

// 3. Log whether alert-box contains 'hidden'

questions.solution:
const btn = document.getElementById('enroll-btn');
const alert = document.getElementById('alert-box');

btn.classList.add('active');
alert.classList.toggle('hidden');

console.log(alert.classList.contains('hidden'));

