questions.starter:
// HTML on the page:
// <div class="course-card"><p class="price">₦10,000</p></div>
// <div class="course-card"><p class="price">₦15,000</p></div>
// <div class="course-card"><p class="price">₦10,500</p></div>

// querySelectorAll all .course-card elements
// Convert to array with Array.from
// filter cards where .price textContent includes '₦10'
// Log the count

questions.solution:
const cards = document.querySelectorAll('.course-card');
const cardArray = Array.from(cards);

const affordable = cardArray.filter(card => {
  return card.querySelector('.price').textContent.includes('₦10');
});

console.log(affordable.length);

