questions.starter:
// HTML on the page:
// <p id="form-message" class="message success">Form submitted!</p>

// 1. Select form-message
// 2. Update textContent to error message
// 3. Add 'error' class, remove 'success' class
// 4. Log className

questions.solution:
const msg = document.getElementById('form-message');
msg.textContent = 'Please enter a valid email address';

msg.classList.add('error');
msg.classList.remove('success');

console.log(msg.className);

questions.starter:
// HTML on the page:
// <span class="price-tag">₦15,000</span>
// <span class="price-tag">₦12,000</span>
// <span class="price-tag">₦10,000</span>

// querySelectorAll .price-tag
// Array.from
// forEach — append ' (VAT inclusive)' to each textContent
// Log each updated price

questions.solution:
const prices = document.querySelectorAll('.price-tag');

Array.from(prices).forEach(price => {
  price.textContent = price.textContent + ' (VAT inclusive)';
  console.log(price.textContent);
});
